{
  "references": [
    {
      "id": "R1",
      "summary_ko": "여성이 수건을 잡는 방식에 문제가 있음."
    },
    {
      "id": "R2",
      "summary_ko": "물컵이 분무기 병으로 변형됨."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "밝기 및 구조 변화 후 복귀하는 깜빡임 또는 순간 변형 패턴 (객체 미식별)."
    },
    {
      "id": "C2",
      "summary_ko": "손을 내릴 때 유리잔이 분무기 병으로 변형됨."
    },
    {
      "id": "C3",
      "summary_ko": "여성이 창턱으로 내릴 때 쥐고 있던 유리잔이 펌프식 분무기 병으로 변형됨."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "후보가 특정 대상을 명시하지 않은 일반적인 깜빡임/변형 측정 가설이어서 동일한 현상인지 판단하기에 정보가 부족합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "수건을 잡는 동작의 결함과 물잔이 분무기로 변형되는 현상은 대상과 오류가 서로 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "수건을 잡는 방식에 관한 문제와 잔이 분무기로 바뀌는 변형 현상은 대상과 결함 내용이 완전히 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "후보 설명이 대상이 식별되지 않은 일반적인 측정 가설이므로 물잔의 분무기 변형과 같은 현상인지 텍스트만으로는 확정할 수 없습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "same",
      "reason_ko": "두 설명 모두 물잔/유리잔이 분무기 병으로 변형되는 동일한 대상을 향한 동일한 현상을 설명합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "same",
      "reason_ko": "두 설명 모두 손에 든 물잔이 분무기 병으로 변형되는 구체적인 오류를 동일하게 기술하고 있습니다."
    }
  ]
}
